function loja(m) {
  if (m.from_name && m.from_name.indexOf("@") === -1) return m.from_name;
  const dominio = (m.from || "").split("@")[1] || m.from || "?";
  return dominio.replace(/^(mail|email|noreply|pedidos|loja)\./, "").split(".")[0];
}

async function run() {
  if (!params.planilha) throw new Error("Escolha a planilha nos ajustes da rotina.");
  const linhas = [];
  const semValor = [];
  for (const m of event.items || []) {
    const j = await judge.compra(m);
    if (j.p < 0.5) continue;
    const achado = money.find((m.subject || "") + " " + (m.snippet || ""));
    const valor = achado ? money.parse(achado) : null;
    if (valor === null) { semValor.push(loja(m) + ": " + (m.subject || "(sem assunto)")); continue; }
    const dia = m.date ? dates.format(m.date, "dd/MM/yyyy") : dates.format(now(), "dd/MM/yyyy");
    linhas.push({row: [dia, loja(m), valor, m.subject || ""], texto: "• " + loja(m) + " — " + money.format(valor, "BRL")});
  }
  if (linhas.length) {
    await sheets.append({sheet: params.planilha, range: params.intervalo, values: linhas.map(l => l.row)});
  }
  if (!linhas.length && !semValor.length) return;
  let text = "";
  if (linhas.length) text += "💳 Anotei na planilha:\n" + linhas.map(l => l.texto).join("\n");
  if (semValor.length) text += (text ? "\n\n" : "") + "Compra sem valor no e-mail, anote à mão:\n" + semValor.map(s => "• " + s).join("\n");
  await notify.send({text});
}
